solution:
const discount = (price, percent) => price * (1 - percent / 100);
const tax = (price, percent) => price * (1 + percent / 100);
const roundMoney = value => Math.round(value * 100) / 100;
function checkout(price) { return roundMoney(tax(discount(price, 10), 8)); }
console.log(checkout(1000));
